513	```ts
514	export type UUID = string;
515	export type ISODate = string;       // 'YYYY-MM-DD'
516	export type ISODateTime = string;   // RFC 3339
517	
518	export type UnitDim = 'mass' | 'volume' | 'count';
519	export type DisplayUnit = 'g' | 'kg' | 'oz' | 'lb' | 'ml' | 'l' | 'tsp' | 'tbsp' | 'cup' | 'fl_oz' | 'pcs';
520	export type ProductSource = 'dataandapis' | 'openfoodfacts' | 'gemini_photo' | 'manual';
521	
522	export type DietFlag = 'vegetarian' | 'vegan' | 'gluten_free' | 'dairy_free' | 'high_protein';
523	// Product decision; aligned with Canada's priority allergens [VERIFY list against Health Canada]
524	export type Allergen =
525	  | 'peanut' | 'tree_nut' | 'sesame' | 'milk' | 'egg' | 'fish'
526	  | 'shellfish' | 'soy' | 'wheat_gluten' | 'mustard' | 'sulphite';
527	
528	export interface Nutrients {          // all nullable; units fixed by name
529	  energyKcal: number | null;
530	  proteinG: number | null;
531	  carbohydrateG: number | null;       // TOTAL carbs incl. fibre (CA/US label convention)
532	  fatG: number | null;
533	  saturatedFatG?: number | null;
534	  sugarsG?: number | null;
535	  fibreG?: number | null;
536	  sodiumMg?: number | null;
537	}
538	
539	export interface UserProfile {
540	  id: UUID;
541	  email: string | null;
542	  displayName: string | null;
543	  avatarUrl: string | null;
544	  tz: string;                         // IANA
545	  dailyKcalGoal: number | null;
546	  dailyProteinGoalG: number | null;
547	  diets: DietFlag[];
548	  allergens: Allergen[];
549	  onboarded: boolean;
550	}
551	
552	export interface Product {
553	  gtin: string;                       // canonical GTIN-13/14
554	  name: string;
555	  brand: string | null;
556	  imageUrl: string | null;
557	  categories: string[];
558	  allergenTags: Allergen[];
559	  packageQuantity: { value: number; unit: 'g' | 'ml' | 'count'; text: string | null } | null;
560	  servingSize: { value: number; unit: 'g' | 'ml'; text: string | null } | null;
561	  basis: '100g' | '100ml';
562	  per100: Nutrients;
563	  perServing: Nutrients | null;
564	  source: Exclude<ProductSource, 'gemini_photo' | 'manual'>;
565	  attribution: string | null;         // e.g. 'Open Food Facts, ODbL'
566	  fetchedAt: ISODateTime;
