569	/** Form model shared by label-photo extraction and the manual product form. */
570	export interface ProductDraft {
571	  gtin: string | null;
572	  name: string;
573	  brand: string | null;
574	  packageQuantity: { value: number; unit: DisplayUnit } | null;
575	  servingSize: { value: number; unit: 'g' | 'ml'; text: string | null } | null;
576	  basis: '100g' | '100ml' | 'serving' | 'unit';
577	  nutrients: Nutrients;               // expressed in `basis`
578	  allergenTags: Allergen[];
579	  source: 'gemini_photo' | 'manual';
580	}
581	
582	export interface PantryItem {
583	  id: UUID;
584	  gtin: string | null;
585	  name: string;
586	  normalizedName: string;
587	  brand: string | null;
588	  dim: UnitDim;
589	  quantityBase: number;
590	  displayUnit: DisplayUnit;
591	  quantityDisplay: string;            // formatted, e.g. '350 g'
592	  gramsPerUnit: number | null;
593	  densityGPerMl: number | null;
594	  expiryDate: ISODate | null;
595	  expirySource: 'photo' | 'manual' | null;
596	  daysToExpiry: number | null;        // computed in user's tz; negative = past date
597	  nutritionBasis: '100g' | '100ml' | 'unit';
598	  nutrition: Nutrients;               // per basis
599	  perServing: Nutrients | null;
