606	
607	export interface RecipeSource {
608	  url: string;                        // final canonical URL (never a vertexaisearch redirect)
609	  siteName: string;
610	  author: string | null;
611	  retrievedAt: ISODateTime;
612	  extractionMethod: 'jsonld' | 'microdata' | 'site-scraper' | 'llm'; // 'llm' → UI shows "may not be verbatim"
613	}
614	
615	export interface RecipeIngredient {
616	  raw: string;                        // EXACT published text — display this
617	  qty: number | null;                 // parsed (for matching/nutrition/deduction only)
618	  unit: DisplayUnit | null;
619	  name: string | null;
620	  normalizedName: string | null;
621	  dim: UnitDim | null;
622	  qtyBase: number | null;             // for recipe's own servings
623	  isStaple: boolean;                  // salt, pepper, water, oil → always 'have'
624	  flags: Array<'unconvertible' | 'negligible' | 'parse_failed'>;
