626	
627	export interface RecipeStep {
628	  index: number;                      // 0-based
629	  text: string;                       // published text (original) or adapted text
630	  timerSeconds: number | null;        // parsed from text; null = no explicit duration
631	  changed?: boolean;                  // true only in AI-adapted variants
632	}
633	
634	export interface OriginalRecipe {
635	  kind: 'original';
636	  recipeId: UUID;
637	  variantId: UUID;
638	  title: string;
639	  source: RecipeSource;
640	  servings: number;                   // from recipeYield; default 4 if unparseable (flagged)
641	  yieldRaw: string | null;
642	  ingredients: RecipeIngredient[];
643	  steps: RecipeStep[];
644	  times: { prepMin: number | null; cookMin: number | null; totalMin: number | null };
