646	}
647	
648	export interface Substitution {
649	  missingIngredient: string;          // as written in the original
650	  substitute: string | null;          // null = omit
651	  pantryItemId: UUID | null;          // must exist in the user's pantry when not null
652	  quantity: string | null;
653	  reason: string;
654	  impact: 'minimal' | 'moderate' | 'significant';
655	}
656	
657	export interface AdaptedRecipe {
658	  kind: 'ai_adapted';
659	  label: 'AI-adapted';
660	  recipeId: UUID;
661	  variantId: UUID;
662	  basedOnVariantId: UUID;             // the original's variantId
663	  substitutions: Substitution[];
664	  ingredients: Array<{ text: string; changed: boolean; parsed: RecipeIngredient }>;
665	  steps: RecipeStep[];                // full step list; changed steps have changed=true
666	  warnings: string[];
667	  model: string;
668	  generatedAt: ISODateTime;
669	}
670	
671	export type MatchStatus = 'have' | 'missing' | 'staple' | 'insufficient';
672	export interface PantryMatch {
673	  ingredientIndex: number;
674	  status: MatchStatus;
675	  pantryItemId: UUID | null;
676	  pantryItemName: string | null;
677	  daysToExpiry: number | null;
678	}
679	
680	export interface DietCheck {
681	  ok: boolean;
682	  violations: Array<{ ingredientRaw: string; rule: DietFlag | Allergen; matchedKeyword: string }>;
683	}
684	
685	export interface NutritionEstimate {
686	  perServing: Nutrients;
687	  coveragePct: number;                // 0–100: share of non-staple ingredients with usable data
688	  basedOn: number;
689	  total: number;
690	  estimatedFields: string[];          // e.g. ['ingredient 3: density assumed 1.0 g/ml']
691	}
692	
693	export interface RecipeScore {
694	  coverage: number;                   // 0–1
695	  expiryScore: number;                // normalized 0–1
696	  missingCount: number;
697	  proteinPerServingG: number | null;
698	  score: number;
699	}
700	
701	export interface RecipeCandidate {
702	  recipeId: UUID;
703	  title: string;
704	  source: RecipeSource;
705	  totalMin: number | null;
706	  servings: number;
707	  score: RecipeScore;
708	  usesExpiring: Array<{ pantryItemId: UUID; name: string; daysToExpiry: number }>;
709	  matches: PantryMatch[];
710	  nutrition: NutritionEstimate;
711	}
712	
713	export type CookingStatus = 'in_progress' | 'finished' | 'abandoned';
714	export interface CookingSession {
715	  id: UUID;
716	  recipeId: UUID;
717	  variantId: UUID;
718	  variantKind: 'original' | 'ai_adapted';
719	  status: CookingStatus;
720	  currentStep: number;
721	  servingsPlanned: number;
722	  startedAt: ISODateTime;
723	  finishedAt: ISODateTime | null;
724	}
725	
726	export interface StepTimer {
727	  id: string;
728	  label: string;                      // 'Step 4 · Simmer sauce'
729	  stepIndex: number;
730	  kind: 'countdown' | 'stopwatch';
731	  durationMs: number | null;          // countdown only
732	  endsAt: number | null;              // epoch ms while running (countdown)
733	  startedAt: number | null;           // epoch ms while running (stopwatch)
734	  pausedRemainingMs: number | null;   // countdown paused
735	  pausedElapsedMs: number | null;     // stopwatch paused
736	  status: 'idle' | 'running' | 'paused' | 'done';
737	}
738	
739	export interface MealLog {
740	  id: UUID;
741	  eatenAt: ISODateTime;
742	  localDate: ISODate;
743	  source: 'cooking_session' | 'manual' | 'pantry_item' | 'barcode';
744	  label: string;
745	  servings: number | null;
746	  kcal: number;
747	  proteinG: number;
748	  carbsG: number | null;
749	  fatG: number | null;
750	  cookingSessionId: UUID | null;
751	  pantryItemId: UUID | null;
752	}
753	
754	export interface DailyTotals {
755	  date: ISODate;
756	  kcal: number;
757	  proteinG: number;
758	  carbsG: number;
759	  fatG: number;
