797	  armHoldMs: number; actionHoldMs: number; armWindowMs: number; alwaysArmed: boolean;
798	  cooldownMs: number; releaseMs: number;
799	  scrollFirstMs: number; scrollRepeatMs: number; scrollFraction: number;
800	  swipeWindowMs: number; swipeMinDx: number; swipeDxToDyRatio: number; swipeMinVelocity: number;
