841	## 7. API route contracts (`src/contracts/api.ts`)
842	
843	General rules for every route:
844	- Node runtime (`export const runtime = 'nodejs'`). The first line is `const user = await requireUser()`, which returns 401 `UNAUTHORIZED` when there is no session.
845	- Bodies are validated with Zod. Errors use the shape below. Success returns the typed payload directly, with no envelope.
846	- The user id comes **only** from the session. Never accept `userId` in a request.
847	- Per-user rate limits (in-memory token bucket in `src/lib/rate-limit.ts`): `/api/recipes/search` 6/min, `/api/recipes/*/adapt` 6/min, `/api/vision/*` 10/min, `/api/tts` 60/min, `/api/products/lookup` 30/min.
848	
849	```ts
850	import type * as D from './domain';
851	
852	export type ApiErrorCode =
853	  | 'UNAUTHORIZED' | 'BAD_REQUEST' | 'NOT_FOUND' | 'CONFLICT' | 'RATE_LIMITED'
854	  | 'UPSTREAM_UNAVAILABLE' | 'UNPROCESSABLE' | 'PAYLOAD_TOO_LARGE' | 'INTERNAL';
855	export interface ApiError { error: { code: ApiErrorCode; message: string; details?: unknown } }
856	
857	// ── Profile ────────────────────────────────────────────────────────────────
858	// GET  /api/me                → D.UserProfile
859	// PATCH /api/me               → D.UserProfile
860	export interface UpdateMeRequest {
861	  displayName?: string;
862	  tz?: string;
863	  dailyKcalGoal?: number | null;
864	  dailyProteinGoalG?: number | null;
865	  diets?: D.DietFlag[];
866	  allergens?: D.Allergen[];
867	  completeOnboarding?: boolean;
868	}
869	
870	// ── Products ───────────────────────────────────────────────────────────────
871	// POST /api/products/lookup
872	export interface ProductLookupRequest { barcode: string }          // digits only, 8–14
873	export interface ProviderAttempt {
874	  provider: 'cache' | 'dataandapis' | 'openfoodfacts';
875	  result: 'hit' | 'miss' | 'error' | 'skipped';
876	  httpStatus?: number;
877	  ms: number;
878	}
879	export type ProductLookupResponse =
880	  | { status: 'found'; product: D.Product; cached: boolean; attempts: ProviderAttempt[] }
881	  | { status: 'not_found'; gtin: string; attempts: ProviderAttempt[] }
882	  | { status: 'invalid_barcode'; reason: 'length' | 'check_digit' | 'non_numeric' };
883	
884	// POST /api/vision/label   multipart/form-data: images (1–3 files, each ≤ 4 MB, jpeg/png/webp/heic), gtin?
885	export interface LabelExtractionResponse {
886	  isFoodProduct: boolean;
887	  draft: D.ProductDraft;                      // source = 'gemini_photo'
888	  flaggedFields: Array<keyof D.Nutrients | 'servingSize' | 'packageQuantity' | 'name'>;
889	  macrosConsistent: boolean | null;           // 4p + 4c + 9f ≈ kcal within ±20%
890	  confidence: 'high' | 'medium' | 'low';
891	  notes: string | null;
892	  model: string;
893	}
894	
895	// POST /api/vision/expiry  multipart/form-data: image (1 file ≤ 4 MB)
896	export interface ExpiryExtractionResponse {
897	  rawText: string | null;
898	  dateType: 'best_before' | 'expiry' | 'use_by' | 'packaged_on' | 'sell_by' | 'unknown';
899	  suggestedDate: D.ISODate | null;            // null if packaged_on or unreadable
900	  candidates: D.ISODate[];                    // >1 when order is ambiguous
901	  needsUserChoice: boolean;
902	  yearInferred: boolean;
903	  regexCrossCheck: 'agree' | 'disagree' | 'no_match';
904	  confidence: 'high' | 'medium' | 'low';
905	}
906	
907	// ── Pantry ─────────────────────────────────────────────────────────────────
908	// GET /api/pantry?sort=expiry|name&includeEmpty=false   → ListPantryResponse
909	export interface ListPantryResponse { items: D.PantryItem[] }
910	// POST /api/pantry                                      → D.PantryItem
911	export interface CreatePantryItemRequest {
912	  gtin?: string | null;
913	  name: string;
914	  brand?: string | null;
915	  quantity: number;                           // in displayUnit
916	  displayUnit: D.DisplayUnit;
917	  gramsPerUnit?: number | null;
918	  densityGPerMl?: number | null;
919	  expiryDate?: D.ISODate | null;
920	  expirySource?: 'photo' | 'manual' | null;
921	  expiryRawText?: string | null;
922	  nutritionBasis: '100g' | '100ml' | 'unit';
923	  nutrition?: D.Nutrients | null;             // per basis
924	  servingSizeBase?: number | null;
925	  allergenTags?: D.Allergen[];
926	  source: D.ProductSource;
927	  userVerified: boolean;
928	}
929	// PATCH /api/pantry/:id                                 → D.PantryItem
930	export type UpdatePantryItemRequest =
931	  Partial<Omit<CreatePantryItemRequest, 'source' | 'gtin'>> & { adjustReason?: 'manual_adjust' | 'discard' };
932	// DELETE /api/pantry/:id                                → { ok: true }
933	
934	// ── Recipes ────────────────────────────────────────────────────────────────
935	// POST /api/recipes/search   → application/x-ndjson stream of RecipeSearchEvent (one JSON per line)
936	export interface RecipeSearchRequest {
937	  mustUsePantryItemIds?: D.UUID[];            // default: items with daysToExpiry ≤ 3
938	  freeText?: string;                          // e.g. 'quick dinner', ≤ 100 chars
939	  maxResults?: number;                        // default 6, max 10
940	  extraDiets?: D.DietFlag[];                  // may only ADD to profile filters, never remove
941	}
942	export type RecipeSearchEvent =
943	  | { type: 'status'; stage: 'searching' | 'resolving' | 'fetching' | 'parsing' | 'checking_diet' | 'ranking'; message: string }
944	  | { type: 'search_suggestions'; html: string }      // Gemini searchEntryPoint.renderedContent, render unmodified
945	  | { type: 'candidate'; candidate: D.RecipeCandidate }
946	  | { type: 'excluded'; url: string; reason: 'no_recipe_markup' | 'fetch_failed' | 'diet_violation' | 'allergen' | 'duplicate' | 'blocked_url'; detail?: string }
947	  | { type: 'done'; total: number; excludedCount: number; cached: boolean }
948	  | { type: 'error'; error: ApiError['error'] };
949	
950	// GET /api/recipes/:id                                  → RecipeDetailResponse
951	export interface RecipeDetailResponse {
952	  original: D.OriginalRecipe;
953	  adaptations: D.AdaptedRecipe[];             // newest first; usually 0 or 1
954	  matches: D.PantryMatch[];
955	  score: D.RecipeScore;
956	  dietCheck: D.DietCheck;
957	  nutrition: { estimate: D.NutritionEstimate; publisher: D.Nutrients | null };
958	  adaptationNutrition: Record<D.UUID, D.NutritionEstimate>;   // keyed by adapted variantId
959	}
960	// POST /api/recipes/:id/adapt   body: {}                → AdaptResponse
961	//   409 CONFLICT  if no missing ingredients
962	//   422 UNPROCESSABLE if validation fails twice (allergen in substitute, unknown pantryItemId, …)
963	export interface AdaptResponse { adaptation: D.AdaptedRecipe; nutrition: D.NutritionEstimate }
964	
965	// ── Cooking ────────────────────────────────────────────────────────────────
966	// POST /api/cook/sessions                               → D.CookingSession
967	export interface StartSessionRequest { recipeId: D.UUID; variantId: D.UUID; servingsPlanned: number }
968	// GET /api/cook/sessions/:id                            → CookSessionView
969	export interface CookSessionView {
970	  session: D.CookingSession;
971	  recipe: { title: string; source: D.RecipeSource; servings: number; isAdapted: boolean };
972	  ingredients: Array<{ text: string; changed: boolean; scaledQtyDisplay: string | null; usedInSteps: number[] }>;
973	  steps: D.RecipeStep[];
974	  substitutions: D.Substitution[];            // empty for originals
975	}
976	// PATCH /api/cook/sessions/:id                          → D.CookingSession
977	export interface UpdateSessionRequest { currentStep?: number; status?: 'abandoned' }
978	// GET /api/cook/sessions/:id/finish-preview?servingsCooked=4   → FinishPreview
979	export interface DeductionLine {
980	  ingredientRaw: string;
981	  pantryItemId: D.UUID | null;
982	  pantryItemName: string | null;
983	  proposedQtyBase: number | null;             // scaled by servingsCooked / variant.servings
984	  availableQtyBase: number | null;
985	  dim: D.UnitDim | null;
986	  display: string;                            // 'Spinach: 150 g of 200 g → 50 g left'
987	  status: 'ok' | 'clamped' | 'unconvertible' | 'no_match' | 'staple';
988	}
989	export interface FinishPreview {
990	  deductions: DeductionLine[];
991	  nutritionPerServing: D.NutritionEstimate;
992	  publisherPerServing: D.Nutrients | null;
993	  suggestedLogPerServing: { kcal: number; proteinG: number; basis: 'estimate' | 'publisher' | 'low_coverage_estimate' };
994	  defaultServingsEaten: number;               // 1
995	}
996	// POST /api/cook/sessions/:id/finish                    → FinishResult
997	//   409 CONFLICT if session not in_progress (idempotency guard)
998	export interface FinishRequest {
999	  servingsCooked: number;                     // > 0, drives deduction
1000	  servingsEaten: number;                      // ≥ 0, drives meal log (0 → no log)
1001	  deductions: Array<{ pantryItemId: D.UUID; qtyBase: number }>;   // user-confirmed lines only
1002	  perServingOverride?: { kcal: number; proteinG: number };
1003	}
1004	export interface FinishResult {
1005	  session: D.CookingSession;
1006	  pantryUpdates: Array<{ pantryItemId: D.UUID; name: string; beforeBase: number; afterBase: number }>;
1007	  mealLog: D.MealLog | null;
1008	}
1009	
1010	// ── Voice ──────────────────────────────────────────────────────────────────
1011	// POST /api/tts   body: TtsRequest   → 200 audio/mpeg (streamed) | ApiError (client falls back)
1012	export interface TtsRequest { text: string /* 1–2000 chars, already speech-normalized */ }
1013	
1014	// ── Nutrition & meals ──────────────────────────────────────────────────────
1015	// GET /api/nutrition/today                 → D.DailyTotals          (from meal_logs by local_date)
1016	// GET /api/nutrition/history?days=7        → { days: D.DailyTotals[] }   (from daily_nutrition cagg; days ≤ 30)
1017	// GET /api/meals?date=YYYY-MM-DD           → { meals: D.MealLog[] }
1018	// POST /api/meals                          → D.MealLog
1019	export type ManualMealRequest =
