  name: string;
  brand: string | null;
  packageQuantity: { value: number; unit: DisplayUnit } | null;
  servingSize: { value: number; unit: 'g' | 'ml'; text: string | null } | null;
  basis: '100g' | '100ml' | 'serving' | 'unit';
