  localDate: ISODate;
  source: 'cooking_session' | 'manual' | 'pantry_item' | 'barcode';
  label: string;
  servings: number | null;
  kcal: number;
  proteinG: number;
  carbsG: number | null;
  fatG: number | null;
  cookingSessionId: UUID | null;
  pantryItemId: UUID | null;
}

export interface DailyTotals {
  date: ISODate;
  kcal: number;
  proteinG: number;
  carbsG: number;
  fatG: number;
  entries: number;
  kcalGoal: number | null;
