export PATH="/c/Program Files/nodejs:$PATH"; node --input-type=module -e "
import postgres from 'postgres';
process.loadEnvFile('.env.local');
for (const name of ['DATABASE_URL_TEST','DATABASE_URL']) {
  const u = new URL(process.env[name]);
  const sql = postgres(process.env[name], { max: 1, ssl: 'require', onnotice: () => {}, connect_timeout: 15 });
  try {
    const ext = await sql\`SELECT extname, extversion FROM pg_extension ORDER BY 1\`;
    const tz = await sql\`SELECT current_setting('TimeZone') tz, version() v\`;
    const mig = await sql\`SELECT to_regclass('schema_migrations') IS NOT NULL AS has\`;
    const applied = mig[0].has ? (await sql\`SELECT version FROM schema_migrations ORDER BY 1\`).map(r=>r.version) : [];
    const tables = (await sql\`SELECT table_name FROM information_schema.tables WHERE table_schema='public' ORDER BY 1\`).map(r=>r.table_name);
    console.log(name, 'host', u.hostname.split('.')[0]+'…', 'db', u.pathname, '| sslmode', u.searchParams.get('sslmode'));
    console.log('  extensions:', ext.map(e=>e.extname+'@'+e.extversion).join(', '));
    console.log('  session tz:', tz[0].tz, '|', tz[0].v.split(' ').slice(0,2).join(' '));
    console.log('  applied:', applied.join(', ') || '(none)', '| tables:', tables.join(', ') || '(none)');
  } catch (e) { console.log(name, 'ERROR', e.code, e.message); }
  await sql.end();
}"

