import postgres from 'postgres';
process.loadEnvFile('.env.local');
const sql = postgres(process.env.DATABASE_URL_TEST, { max: 1, ssl: 'require', onnotice: () => {} });
class Rollback extends Error {}
try {
  await sql.begin(async (tx) => {
    const [u] = await tx\`INSERT INTO users (auth0_sub) VALUES ('probe|realtime-check') RETURNING id\`;
    await tx\`INSERT INTO meal_logs (user_id, local_date, source, label, kcal, protein_g) VALUES (\${u.id}, (now() AT TIME ZONE 'America/Vancouver')::date, 'manual', 'probe', 540, 32)\`;
    const rows = await tx\`SELECT day, kcal::float, protein_g::float, entries::int FROM daily_nutrition WHERE user_id = \${u.id}\`;
    console.log('daily_nutrition right after insert:', JSON.stringify(rows));
    const plan = (await tx.unsafe(\"EXPLAIN SELECT day, kcal FROM daily_nutrition WHERE user_id = '\" + u.id + \"' AND day >= now() - interval '7 days'\")).map(r=>r['QUERY PLAN']).join('\n');
    console.log('plan mentions materialized hypertable:', /_materialized_hypertable/.test(plan), '| raw meal_logs (real-time part):', /meal_logs|_hyper_1_/.test(plan));
    throw new Rollback();
  });
} catch (e) { if (!(e instanceof Rollback)) console.log('ERROR', e.code, e.message); }
console.log('probe user left behind:', (await sql\`SELECT count(*)::int n FROM users WHERE auth0_sub='probe|realtime-check'\`)[0].n);
await sql.end();"

